const Database = require('better-sqlite3');

/**
 * @param {string} file - sqlite file path
 * @param {boolean} safeMode - when true, enforce UNIQUE(code) on redemptions
 */
function openDb(file, safeMode) {
  const db = new Database(file);
  db.pragma('journal_mode = WAL');

  db.exec(`
    CREATE TABLE IF NOT EXISTS coupons (
      code          TEXT PRIMARY KEY,
      amount_cents  INTEGER NOT NULL,
      redeemed      INTEGER NOT NULL DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS redemptions (
      id         INTEGER PRIMARY KEY AUTOINCREMENT,
      code       TEXT NOT NULL,
      user_id    TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
      ${safeMode ? ', UNIQUE (code)' : ''}
    );
  `);

  db.prepare(
    `INSERT OR IGNORE INTO coupons (code, amount_cents) VALUES ('SAVE10', 1000)`
  ).run();

  return db;
}

module.exports = { openDb };
"})
