result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/server.js", "content": "'use strict';
const express = require('express');
const { openDb } = require('./db');

// REDEEM_MODE=naive (buggy SELECT-then-INSERT) | safe (UNIQUE constraint)
const MODE = process.env.REDEEM_MODE || 'safe';
const PORT = Number(process.env.PORT || 3000);
const DB_FILE = process.env.DB_FILE || `./data-${MODE}-${process.pid}.db`;

const db = openDb(DB_FILE, MODE === 'safe');

const app = express();
app.use(express.json());

const getRedemption = db.prepare('SELECT 1 FROM redemptions WHERE code = ?');
const insertRedemption = db.prepare(
  'INSERT INTO redemptions (code, user_id) VALUES (?, ?)'
);

function naiveRedeem(req, res) {
  const { code, user_id: userId } = req.body ?? {};

  // Step 1: check
  const already = getRedemption.get(code);
  if (already) {
    return res.status(409).json({ error: 'already_redeemed' });
  }

  // Simulate async work between CHECK and WRITE (e.g. fraud check, logging
  // to another service). This yields the event loop and opens the race
  // window where other requests pass the same check.
  return setTimeout(() => {
    // Step 2: write -- no uniqueness guard, so N requests can all land here
    try {
      const info = insertRedemption.run(code, userId);
      res.status(200).json({ ok: true, redemption_id: info.lastInsertRowid });
    } catch (err) {
      res.status(500).json({ error: 'internal' });
    }
  }, 5);
}

function safeRedeem(req, res) {
  const { code, user_id: userId } = req.body ?? {};

  // Single atomic write; UNIQUE(code) is the source of truth.
  try {
    const info = insertRedemption.run(code, userId);
    return res.status(200).json({ ok: true, redemption_id: info.lastInsertRowid });
  } catch (err) {
    if (err && err.code === 'SQLITE_CONSTRAINT_UNIQUE') {
      return res.status(409).json({ error: 'already_redeemed' });
    }
    throw err;
  }
}

app.post('/redeem', MODE === 'naive' ? naiveRedeem : safeRedeem);

if (require.main === module) {
  app.listen(PORT, () => console.log(`${MODE} server listening on ${PORT}`));
}

module.exports = { app, db, MODE, DB_FILE };
"})
