result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/redeem.test.js", "content": "'use strict';
// FINAL COMMITTED CONTRACT: exactly ONE of 20 concurrent redemptions gets
// 200, the rest get 409 {"error":"already_redeemed"}, and the redemptions
// table holds exactly one row.
const test = require('node:test');
const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const { mkdtempSync } = require('node:fs');
const { tmpdir } = require('node:os');
const { join } = require('node:path');
const { setTimeout: sleep } = require('node:timers/promises');

async function withSafeServer(fn) {
  const dir = mkdtempSync(join(tmpdir(), 'coupon-safe-'));
  const child = spawn(process.execPath, ['src/server.js'], {
    cwd: join(__dirname, '..'),
    env: {
      ...process.env,
      REDEEM_MODE: 'safe',
      DB_FILE: join(dir, 'test.db'),
    },
    stdio: ['ignore', 'pipe', 'pipe'],
  });

  let port = null;
  let stderr = '';
  child.stdout.on('data', (d) => {
    const m = /listening on (\d+)/.exec(String(d));
    if (m) port = Number(m[1]);
  });
  child.stderr.on('data', (d) => (stderr += String(d)));

  for (let i = 0; i < 100 && !port; i++) await sleep(25);
  assert.ok(port, `server did not start\n${stderr}`);
  const base = `http://127.0.0.1:${port}`;

  try {
    return await fn({ base, dbFile: join(dir, 'test.db') });
  } finally {
    child.kill('SIGTERM');
  }
}

function redeem(base, userId) {
  return fetch(`${base}/redeem`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ code: 'SAVE10', user_id: userId }),
  });
}

test('exactly one 200 among 20 concurrent attempts; one row in redemptions', async () => {
  await withSafeServer(async ({ base, dbFile }) => {
    const responses = await Promise.all(
      Array.from({ length: 20 }, (_, i) => redeem(base, `user-${i}`))
    );

    const bodies = await Promise.all(responses.map((r) => r.json()));
    const statuses = responses.map((r) => r.status);

    // Exactly one winner...
    assert.equal(statuses.filter((s) => s === 200).length, 1,
      `expected exactly one 200, got: [${statuses.join(',')}]`);

    // ...everyone else is rejected with the canonical conflict payload
    for (let i = 0; i < responses.length; i++) {
      if (statuses[i] !== 200) {
        assert.equal(statuses[i], 409);
        assert.deepEqual(bodies[i], { error: 'already_redeemed' });
      }
    }

    // And the database agrees: exactly one redemption row exists.
    const { Database } = require('better-sqlite3');
    const db = new Database(dbFile, { readonly: true });
    const count = db.prepare('SELECT COUNT(*) AS n FROM redemptions').get().n;
    const rows = db.prepare('SELECT code, user_id FROM redemptions').all();
    db.close();
    assert.equal(count, 1);
    assert.equal(rows[0].code, 'SAVE10');
  });
});
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/naive.race.test.js", "content": "'use strict';
// BUG DEMONSTRATION (kept as documentation, not part of the committed
// contract): against the naive SELECT-then-INSERT implementation, firing 20
// parallel redemptions through the real HTTP server yields MORE THAN ONE
// success. This test asserts the buggy behaviour to prove the race exists.
const test = require('node:test');
const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const { mkdtempSync } = require('node:fs');
const { tmpdir } = require('node:os');
const { join } = require('node:path');
const { setTimeout: sleep } = require('node:timers/promises');

test('NAIVE implementation loses the race: >1 of 20 parallel redemptions succeed', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'coupon-naive-'));
  const child = spawn(process.execPath, ['src/server.js'], {
    cwd: join(__dirname, '..'),
    env: {
      ...process.env,
      REDEEM_MODE: 'naive',
      DB_FILE: join(dir, 'test.db'),
    },
    stdio: ['ignore', 'pipe', 'pipe'],
  });

  let port = null;
  child.stdout.on('data', (d) => {
    const m = /listening on (\d+)/.exec(String(d));
    if (m) port = Number(m[1]);
  });
  for (let i = 0; i < 100 && !port; i++) await sleep(25);
  assert.ok(port, 'naive server did not start');

  try {
    const responses = await Promise.all(
      Array.from({ length: 20 }, (_, i) =>
        fetch(`http://127.0.0.1:${port}/redeem`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ code: 'SAVE10', user_id: `user-${i}` }),
        })
      )
    );
    const statuses = responses.map((r) => r.status);
    const successes = statuses.filter((s) => s === 200).length;

    // The bug, stated as an assertion:
    console.log(`    naive server: ${successes}/20 requests got 200 (expected exactly 1)`);
    assert.ok(successes > 1,
      `race window did not reproduce (only ${successes} succeeded) — flaky demo`);

    const { Database } = require('better-sqlite3');
    const db = new Database(join(dir, 'test.db'), { readonly: true });
    const rows = db.prepare('SELECT COUNT(*) AS n FROM redemptions').get().n;
    db.close();
    console.log(`    naive server: ${rows} rows in redemptions for a single-use coupon`);
    assert.ok(rows > 1);
  } finally {
    child.kill('SIGTERM');
  }
});
"})
